CREATE TABLE productos(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo varchar(255) NOT NULL UNIQUE,nombre varchar(255) NOT NULL,descripcion varchar(2000) NOT NULL,categoria varchar(255) NOT NULL,tono varchar(255) NOT NULL,precio_compra numeric(14,2) NOT NULL CHECK(precio_compra>=0),precio_venta numeric(14,2) NOT NULL CHECK(precio_venta>=precio_compra),imagen varchar(255) NOT NULL DEFAULT '',activo boolean NOT NULL DEFAULT true);CREATE INDEX productos_activo_idx ON productos(activo);